
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_xc_gas22_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_xc_gas22", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.230128919329111e+00, -4.130731298277712e+00, -3.991580624852294e+00, -3.799213748912131e+00, -3.538261180682111e+00, -3.194360275779995e+00, -2.760941994158138e+00, -2.250056098677462e+00, -1.699003606655537e+00, -1.165739212161426e+00, -7.204388825243727e-01, -4.873731701755772e-01, -4.215003277871027e-01, -3.171730941141927e-01, -1.981669922513132e-01, -8.635074053537632e-02, -6.203896963111788e-02, -4.715924721202155e-02, -1.629803841640973e-02, -2.471693187127783e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


